+  const template = "{{#if account}}{{#if account.active}}yes{{else}}no{{/if}}{{else}}missing{{/if}}";
+  expect(render(template, { account: { active: false } })).toBe("no");
+  expect(render(template, { account: null })).toBe("missing");
+  expect(render("{{#if values}}present{{else}}empty{{/if}}", { values: [] })).toBe("empty");
+});
+
+test("supports loops, root fallback, and nested loops", () => {
+  const template = "{{#each groups}}[{{title}}:{{#each this}}{{@index}}={{this}}/{{title}};{{/each}}]{{else}}none{{/each}}";
+  expect(render(template, { title: "root", groups: [["a", "b"], ["c"]] })).toBe("[root:0=a/root;1=b/root;][root:0=c/root;]");
+  expect(render("{{#each items}}{{this}}{{else}}empty{{/each}}", { items: [] })).toBe("empty");
+});
+
+test("omits comments and missing values", () => {
+  expect(render("A{{! ignored }}{{missing.value}}B", {})).toBe("AB");
+});
+
+test("reports structural and scalar errors", () => {
+  expect(() => render("{{#wat x}}{{/wat}}", {})).toThrow(/Unknown or malformed block at line 1, column 1/);
+  expect(() => render("{{#if x}}{{/each}}", {})).toThrow(/Mismatched closing tag/);
+  expect(() => render("{{else}}", {})).toThrow(/Else outside a block/);
+  expect(() => render("{{#if x}}{{else}}{{else}}{{/if}}", { x: true })).toThrow(/Duplicate else/);
+  expect(() => render("{{#if x}}", { x: true })).toThrow(/Unclosed block/);
+  expect(() => render("{{value}}", { value: {} })).toThrow(/Cannot render object/);
+});

